CREATE TABLE IF NOT EXISTS panel_drop_rule (rule_key VARCHAR(80) PRIMARY KEY, category VARCHAR(40) NOT NULL, base_percent DECIMAL(12,8) NOT NULL, percent_override DECIMAL(12,8) NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS panel_drop_runtime (id TINYINT PRIMARY KEY, heartbeat DATETIME NULL, applied_revision BIGINT NOT NULL DEFAULT 0);
